\begin{theorem}
If $f(x) = x^2$, then $f'(x) = 2x$.
\end{theorem}

\begin{proof}
By definition,
\begin{align}
  f'(x) &= \lim_{h \to 0} \frac{(x+h)^2 - x^2}{h} \\
        &= \lim_{h \to 0} \frac{2xh + h^2}{h} \\
        &= \lim_{h \to 0} (2x + h) \\
        &= 2x.
\end{align}
\end{proof}
